const http = require('http');
const fs = require('fs');
const path = require('path');

const endpoint = 'http://127.0.0.1:63683/status';

http.get(endpoint, (res) => {
  let body = '';
  res.on('data', (chunk) => {
    body += chunk;
  });
  res.on('end', () => {
    const outDir = path.join(__dirname, 'results');
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(
      path.join(outDir, 'status.json'),
      JSON.stringify({ status: res.statusCode }, null, 2) + '\n'
    );
    console.log(`status=${res.statusCode}`);
  });
}).on('error', (err) => {
  console.error(err);
  process.exit(1);
});

